              "chapter_title": {
                "type": "string",
                "description": "章节标题"
              },
              "chapter_synopsis": {
                "type": "string",
                "description": "本章故事梗概（自然语言叙述，200-400字）- 描述起始状态、主角核心行动、主要冲突展开、在整幕中的作用、结束状态",
                "minLength": 200,
                "maxLength": 400
              },
              "scene_sequence": {
                "type": "array",
                "description": "本章场景序列（按时间顺序排列，至少3个场景）",
                "minItems": 3,
                "items": {
                  "type": "object",
                  "required": [
                    "scene_number",
                    "scene_location",
                    "characters_present",
                    "scene_purpose",
                    "core_action",
                    "conflict_point",
                    "emotional_shift",
                    "scene_outcome"
                  ],
                  "properties": {
                    "scene_number": {
                      "type": "integer",
                      "minimum": 1,
                      "description": "场景编号（章内序号）"
                    },
                    "scene_location": {
                      "type": "string",
                      "description": "场景地点（具体环境）"
                    },
                    "characters_present": {
                      "type": "array",
                      "description": "在场角色",
                      "items": {
                        "type": "string"
                      },
                      "minItems": 1
                    },
                    "scene_purpose": {
                      "type": "string",
                      "description": "本场景在chapter_synopsis中的作用"
                    },
                    "core_action": {
                      "type": "string",
                      "description": "核心动作（谁对谁做了什么，必须是可视化的具体行为，不能是抽象表述）"
                    },
                    "conflict_point": {
                      "type": "string",
                      "description": "本场景的冲突爆发点"
                    },
                    "emotional_shift": {
                      "type": "string",
                      "description": "本场景中主角的情感变化（从A到B）"
